export const BANK=[];
// Question ids used to be `subject-level-<global insertion index>`, so inserting or
// reordering anything repointed every saved retirement flag after it and the bank
// could only ever be appended to. Ids are now derived from the question's own text,
// which makes them stable under insertion, reordering and deduplication.
// LEGACY maps every old positional id to its new stable id, including ids that were
// dropped as duplicates - core/save.js uses it to migrate v1 saves.
export const LEGACY=new Map();
const seen=new Map();
export const hash=s=>{let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(36);};
let added=0;
function add(subject,level,tier,topic,prompt,answer,explanation,options){
 const legacyId=`${subject}-${level}-${added++}`,key=subject+'|'+level+'|'+prompt;
 // The parameterized generators emit some prompts repeatedly. Keep the first; point
 // the duplicates' legacy ids at it so a player who retired one keeps that progress.
 if(seen.has(key)){LEGACY.set(legacyId,seen.get(key));return;}
 const id=`${subject}-${level}-${hash(prompt)}`;
 seen.set(key,id);LEGACY.set(legacyId,id);
 BANK.push({id,subject,level,tier,topic,prompt,answer,explanation,options,numeric:typeof answer==='number'});}
// Parameterized items use bounded, explicit arithmetic; no live AI or external API.
for(let i=1;i<=45;i++){
 const a=i+3,b=i%8+2;
 add('math',0,i%3,'arithmetic',`What is ${a} × ${b}?`,a*b,`Multiply ${a} by ${b}: ${a*b}.`);
 add('math',0,i%3,'fractions',`What is ${b}/10 of ${a*10}?`,a*b,`Divide ${a*10} by 10, then multiply by ${b}.`);
 add('math',0,i%3,'equations',`Solve for x: x + ${b} = ${a+b}.`,a,`Subtract ${b} from both sides.`);
 add('math',1,i%3,'algebra',`Solve for x: ${b}x − ${a} = ${a*b-a}.`,a,`Add ${a} to both sides and divide by ${b}.`);
 add('math',1,i%3,'functions',`If f(x) = ${b}x², what is f(${a})?`,b*a*a,`Square ${a}, then multiply by ${b}.`);
 add('math',1,i%3,'probability',`A bag has ${b} red and ${10-b} blue counters. If one counter is drawn uniformly at random, what is the probability of red, as a decimal?`,b/10,`There are 10 equally likely counters; ${b} are red.`);
 add('math',2,i%3,'derivatives',`For f(x) = ${b}x² + ${a}x, find f′(2).`,4*b+a,`The derivative is ${2*b}x + ${a}. Evaluate at x = 2.`);
 add('math',2,i%3,'integration',`Evaluate the integral of ${2*b}x from 0 to ${a}.`,b*a*a,`An antiderivative is ${b}x². Evaluate at ${a} and subtract its value at 0.`);
 add('math',2,i%3,'linear algebra',`Find the determinant of the 2×2 matrix [[${a}, 1], [2, ${b}]].`,a*b-2,'For [[a,b],[c,d]], the determinant is ad − bc.');
 add('cs',0,i%3,'binary',`Convert the binary number ${(i+1).toString(2)} to decimal.`,i+1,'Add the powers of two for positions containing 1, starting with 1 at the right.');
 add('cs',0,i%3,'algorithms',`A loop prints one dot ${a} times. How many dots are printed?`,a,'One output per iteration means the output count equals the iteration count.');
 add('cs',0,i%3,'data',`A file contains ${a} bytes. How many bits is that?`,a*8,'One byte contains 8 bits.');
 add('cs',1,i%3,'logic',`In JavaScript, what is ${a} % ${b}?`,a%b,'The remainder operator returns what remains after integer division.');
 add('cs',1,i%3,'loops',`An outer loop runs ${a} times and an inner loop runs ${b} times per outer iteration. How many inner iterations occur?`,a*b,'Multiply the loop counts for nested independent loops.');
 add('cs',1,i%3,'arrays',`An array has ${a+2} elements and starts at index 0. What is its last valid index?`,a+1,'The last index is the length minus one.');
 add('cs',2,i%3,'graphs',`How many edges are in a complete undirected simple graph with ${a} vertices?`,a*(a-1)/2,'Every pair shares one edge: n(n−1)/2.');
 add('cs',2,i%3,'memory',`A byte-addressed machine uses ${b+4} address bits. How many distinct bytes can it address?`,2**(b+4),'With n address bits, there are 2ⁿ distinct addresses.');
 add('cs',2,i%3,'analysis',`A linear scan makes n comparisons; a nested full scan makes n². At n = ${a}, how many more comparisons does the nested scan make?`,a*a-a,'Compute n² − n.');
 add('science',0,i%3,'measurement',`Convert ${a} metres to centimetres.`,a*100,'There are 100 centimetres in one metre.');
 add('science',0,i%3,'motion',`A cyclist travels ${a*b} metres in ${b} seconds. What is the average speed in m/s?`,a,'Average speed = distance ÷ elapsed time.');
 add('science',0,i%3,'matter',`A sample has mass ${a*b} g and volume ${b} cm³. Find its density in g/cm³.`,a,'Density = mass ÷ volume.');
 add('science',1,i%3,'forces',`A ${a} kg object accelerates at ${b} m/s². What is the net force in newtons?`,a*b,'Newton’s second law: F = ma.');
 add('science',1,i%3,'electricity',`A current of ${b} A flows through ${a} ohms. Find the voltage in volts.`,a*b,'Ohm’s law: V = IR.');
 add('science',1,i%3,'chemistry',`A sample contains ${b} moles of a substance with molar mass ${a} g/mol. What is its mass in grams?`,a*b,'Mass = amount in moles × molar mass.');
 add('science',2,i%3,'mechanics',`A ${2*a} kg object moves at ${b} m/s. Find its kinetic energy in joules.`,a*b*b,'Kinetic energy = ½mv².');
 add('science',2,i%3,'thermodynamics',`An ideal gas absorbs ${a*10} J of heat and does ${b*10} J of work. Find ΔU in joules.`,(a-b)*10,'Using work done by the gas, ΔU = Q − W.');
 add('science',2,i%3,'kinetics',`A first-order reaction has half-life ${a} minutes. What percentage of reactant remains after ${a*2} minutes?`,25,'Two half-lives leave (1/2)² = 25%.');
 add('finance',0,i%3,'budgeting',`You have ${a*10} coins and spend ${b} coins. How many remain?`,a*10-b,'Subtract spending from the starting balance.');
 add('finance',0,i%3,'prices',`You buy ${b} notebooks at ${a} coins each. What is the total cost?`,a*b,'Total cost = quantity × unit price.');
 add('finance',0,i%3,'saving',`You save ${a} coins each week for ${b} weeks. How many coins do you save?`,a*b,'Multiply the weekly saving by the number of weeks.');
 add('finance',1,i%3,'interest',`A principal of ${a*100} earns ${b}% simple annual interest for 1 year. How much interest is earned?`,a*b,'Simple interest = principal × annual rate × years.');
 add('finance',1,i%3,'profit',`Revenue is ${a*100} and total costs are ${b*10}. What is profit?`,a*100-b*10,'Profit = revenue − total costs.');
 add('finance',1,i%3,'percentages',`An item costs ${a*100} coins before a ${b}% discount. How many coins is the discount?`,a*b,'Discount amount = original price × discount rate.');
 add('finance',2,i%3,'present value',`A payment of ${a*110} is due in one year. At a 10% annual discount rate, what is its present value?`,a*100,'Present value = future payment ÷ 1.10.');
 add('finance',2,i%3,'marginal analysis',`Total cost is C(q) = ${b}q² + ${a}q. What is marginal cost at q = 2?`,4*b+a,`Differentiate cost: C′(q) = ${2*b}q + ${a}.`);
 add('finance',2,i%3,'multipliers',`In a simple closed economy with no taxes, the marginal propensity to consume is ${(1-1/b).toFixed(6)} (approximately). What is the spending multiplier, rounded to the nearest whole number?`,b,'In this fixed-price expenditure model, use 1/(1 − MPC), then round to the nearest whole number.');
}
