for(const [subject,levels] of Object.entries(extra))levels.forEach((rows,level)=>rows.forEach(r=>add(subject,level,r[0],r[1],r[2],r[3],r[4],[r[3],r[5],r[6],r[7]])));

// Second expansion. Ids are content-derived, so this block may sit anywhere in the file.
// Every parameter these loops vary is named in the prompt sentence itself, so each
// iteration produces a distinct question rather than a repeat that add() would drop.
for(let i=0;i<13;i++){
 const a=i+4,d=i%4+2,s=i%5+1;
 add('math',1,i%3,'sequences',`An arithmetic sequence starts at ${a} and adds ${d} each term. What is the 5th term?`,a+4*d,'The nth term is the first term plus (n − 1) common differences, so the 5th term adds four of them.');
 add('math',1,i%3,'coordinate geometry',`What is the slope of the line through (2, ${a}) and (5, ${a+3*s})?`,s,'Slope is the change in y divided by the change in x between the two points.');
 add('math',1,i%3,'quadratics',`Solve x² − ${a+3}x + ${3*a} = 0 and give the larger root.`,a,`The left side factors as (x − 3)(x − ${a}), and a product is zero only when one factor is zero.`);
}
for(let k=1;k<=13;k++){
 add('cs',2,k%3,'trees',`A perfect binary tree has height ${k}, counting the root as height 0. How many nodes does it contain?`,2**(k+1)-1,'Each level holds twice the nodes of the one above, and those powers of two sum to 2^(h+1) − 1.');
 add('cs',2,k%3,'graphs',`A tree — a connected undirected graph with no cycles — has ${k+5} vertices. How many edges does it have?`,k+4,'Pick any vertex as the root: every other vertex joins its parent by exactly one edge, so a tree on n vertices has n\u00a0−\u00a01 edges.');
 add('cs',2,k%3,'analysis',`Merge sort makes about n log₂ n comparisons. What is that value for n = ${2**k}?`,k*2**k,'Take log₂ of n first, then multiply that exponent back by n. This is the usual estimate and an upper bound: for n a power of two, merge sort’s worst case is n log₂ n − n + 1 comparisons.');
}
for(let i=0;i<13;i++){
 const n=i+1;
 add('finance',2,i%3,'compounding',`An account holding ${100*n} earns 10% interest compounded annually. What is the balance after 2 years?`,121*n,'Compounding pays the second year’s interest on the first year’s interest as well as on the principal.');
 add('finance',2,i%3,'valuation',`A perpetuity pays ${50*(n+1)} every year forever, starting one year from now. At a 5% annual discount rate, what is its present value?`,1000*(n+1),'With the first payment one year from now, sum the discounted annual payments: present value = annual payment ÷ annual discount rate.');
 add('finance',2,i%3,'break-even',`Fixed costs are ${500*n}, each unit sells for 15 and costs 10 to produce. How many units must be sold to break even?`,100*n,'Each unit leaves 5 after variable costs, so divide fixed costs by that contribution margin.');
}
